import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public class AdminDashboard extends JFrame {
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Equipment","Category","Total","Available","Status"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public AdminDashboard(){setTitle("Admin Dashboard - "+Session.name);setSize(900,520);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);JPanel p=new JPanel();String[] names={"Add","Update","Delete","Refresh","Manage Bookings","Reports","Logout"};for(String n:names){JButton b=new JButton(n);p.add(b);if(n.equals("Add"))b.addActionListener(e->addEquipment());if(n.equals("Update"))b.addActionListener(e->updateEquipment());if(n.equals("Delete"))b.addActionListener(e->deleteEquipment());if(n.equals("Refresh"))b.addActionListener(e->load());if(n.equals("Manage Bookings"))b.addActionListener(e->new ManageBookingsFrame().setVisible(true));if(n.equals("Reports"))b.addActionListener(e->new ReportsFrame().setVisible(true));if(n.equals("Logout"))b.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});}add(p,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);load();}
    private void load(){model.setRowCount(0);String s="SELECT e.equipment_id,e.equipment_name,c.category_name,e.total_quantity,e.available_quantity,e.status FROM equipment e JOIN categories c ON e.category_id=c.category_id ORDER BY e.equipment_id";try(Connection c=DBConnection.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(s)){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getInt(4),r.getInt(5),r.getString(6)});}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private int category(Connection c,String name)throws SQLException{PreparedStatement p=c.prepareStatement("SELECT category_id FROM categories WHERE category_name=?");p.setString(1,name);ResultSet r=p.executeQuery();if(r.next())return r.getInt(1);p=c.prepareStatement("INSERT INTO categories(category_name) VALUES(?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,name);p.executeUpdate();r=p.getGeneratedKeys();r.next();return r.getInt(1);}
    private void addEquipment(){String name=JOptionPane.showInputDialog(this,"Equipment name:");if(name==null||name.isBlank())return;String cat=JOptionPane.showInputDialog(this,"Category:");String q=JOptionPane.showInputDialog(this,"Total quantity:");try(Connection c=DBConnection.getConnection()){int qty=Integer.parseInt(q);if(qty<0)throw new Exception("Invalid quantity");int cid=category(c,cat);PreparedStatement p=c.prepareStatement("INSERT INTO equipment(equipment_name,category_id,total_quantity,available_quantity,status) VALUES(?,?,?,?,?)");p.setString(1,name);p.setInt(2,cid);p.setInt(3,qty);p.setInt(4,qty);p.setString(5,qty>0?"Available":"Unavailable");p.executeUpdate();load();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private void updateEquipment(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select equipment");return;}int id=(int)model.getValueAt(row,0);String name=JOptionPane.showInputDialog(this,"Equipment name:",model.getValueAt(row,1));String q=JOptionPane.showInputDialog(this,"Total quantity:",model.getValueAt(row,3));try(Connection c=DBConnection.getConnection()){int oldTotal=(int)model.getValueAt(row,3),oldAvail=(int)model.getValueAt(row,4),newTotal=Integer.parseInt(q),borrowed=oldTotal-oldAvail,newAvail=newTotal-borrowed;if(newAvail<0)throw new Exception("Total cannot be less than currently borrowed quantity");PreparedStatement p=c.prepareStatement("UPDATE equipment SET equipment_name=?,total_quantity=?,available_quantity=?,status=? WHERE equipment_id=?");p.setString(1,name);p.setInt(2,newTotal);p.setInt(3,newAvail);p.setString(4,newAvail>0?"Available":"Unavailable");p.setInt(5,id);p.executeUpdate();load();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private void deleteEquipment(){int row=table.getSelectedRow();if(row<0)return;int id=(int)model.getValueAt(row,0);try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM equipment WHERE equipment_id=?")){p.setInt(1,id);p.executeUpdate();load();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Cannot delete equipment with booking history");}}
}
